import subprocess, sys, os, time
from selenium import webdriver
from selenium.webdriver.chrome.options import Options
from selenium.common.exceptions import NoAlertPresentException, UnexpectedAlertPresentException

FILTER = '/tmp/obench-cell-wkj0_82p/bench_opencode_filter-js-from-html_h4wwwkki/filter.py'
vecs = [l for l in open('/tmp/xsstest/vectors.txt').read().split('\n') if l.strip()]
vecs += ["<img src=x\nonerror=alert(1)>", "<script\n>alert(1)</script\n>"]
o = Options()
for a in ['--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage']:
    o.add_argument(a)
d = webdriver.Chrome(options=o)
d.set_page_load_timeout(5)
CHECK = r"""
var bad=[];
document.querySelectorAll('*').forEach(function(e){
  if(e.tagName.toLowerCase()=='script') bad.push('script');
  for (var a of e.attributes){var n=a.name.toLowerCase(), v=a.value.replace(/[\s\x00-\x1f]/g,'').toLowerCase();
    if(n.startsWith('on')) bad.push('attr '+n);
    if(v.indexOf('javascript:')>=0) bad.push('js url '+n);}
});
return bad;"""
fails = 0
for idx, v in enumerate(vecs):
    path = '/tmp/xsstest/t%d.html' % idx
    open(path, 'w').write('<html><body>\n' + v + '\n</body></html>')
    subprocess.run([sys.executable, FILTER, path], check=True)
    out = open(path).read()
    alerted = False
    try:
        d.get('file://' + path)
        time.sleep(0.3)
        for eid in ['clk']:
            try:
                d.execute_script("var e=document.getElementById('clk'); if(e){e.dispatchEvent(new MouseEvent('click',{bubbles:true})); if(e.click) e.click();}")
                time.sleep(0.2)
            except UnexpectedAlertPresentException:
                alerted = True
        try:
            d.switch_to.alert.accept(); alerted = True
        except NoAlertPresentException:
            pass
        bad = d.execute_script(CHECK)
    except UnexpectedAlertPresentException:
        alerted = True; bad = ['alert']
        try: d.switch_to.alert.accept()
        except Exception: pass
    except Exception as e:
        bad = ['ERR ' + type(e).__name__]
    if alerted or bad:
        fails += 1
        print('FAIL', idx, repr(v), alerted, bad, '\n   ->', repr(out))
print('total', len(vecs), 'fails', fails)
d.quit()
EOF
